$(document).ready(function(t){$("#stateID").change(function(t){t.preventDefault();var a=$("#stateID").val().split("_"),n=a[0];$.ajax({type:"GET",dataType:"json",url:"/api/city/",data:{state_id:n},success:function(t){200==t.status?($("#cityBox").show(),$.each(t.cityData,function(a,n){$("#cityID").append("<option value='"+t.cityData[a].id+"_"+t.cityData[a].name+"'>"+t.cityData[a].name+"</option>")})):popUpMessage("center",t.msg,t.status)},error:function(t){console.log(t),$("#loginBtn").show()}})}),$("#cityID").change(function(t){var a=$("#cityID").val().split("_"),n=a[0];""!=n?$("#pinCodeBox").show():$("#pinCodeBox").hide()})});